def parse_excel_date(value: Any) -> date:
    """Parse a cell that may contain an Excel serial, datetime, or string.

    Returns a ``datetime.date`` object. Raises ``ValueError`` if parsing fails.
    """
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        # Excel's epoch is 1899‑12‑30 (with the 1900 leap‑year bug).
        # openpyxl provides ``openpyxl.utils.datetime.from_excel`` but to avoid
        # importing the whole utils we compute manually.
        return datetime.fromordinal(datetime(1899, 12, 30).toordinal() + int(value)).date()
    if isinstance(value, str):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d", "%d-%b-%Y"):
            try:
                return datetime.strptime(value.strip(), fmt).date()
            except Exception:
                continue
    raise ValueError(f"Unrecognised date format: {value!r}")

